    /**
     * Selects a collection of UnidadDocumental objects pre-filled with all related objects except LocalizacionUnidadDocumental.
     *
     * @param      Criteria  $criteria
     * @param      PropelPDO $con
     * @param      String    $join_behavior the type of joins to use, defaults to Criteria::LEFT_JOIN
     * @return array           Array of UnidadDocumental objects.
     * @throws PropelException Any exceptions caught during processing will be
     *		 rethrown wrapped into a PropelException.
     */
    public static function doSelectJoinAllExceptLocalizacionUnidadDocumental(Criteria $criteria, $con = null, $join_behavior = Criteria::LEFT_JOIN)
    {
        $criteria = clone $criteria;

        // Set the correct dbName if it has not been overridden
        // $criteria->getDbName() will return the same object if not set to another value
        // so == check is okay and faster
        if ($criteria->getDbName() == Propel::getDefaultDB()) {
            $criteria->setDbName(UnidadDocumentalPeer::DATABASE_NAME);
        }

        UnidadDocumentalPeer::addSelectColumns($criteria);
        $startcol2 = UnidadDocumentalPeer::NUM_HYDRATE_COLUMNS;

        SoporteUnidadDocumentalPeer::addSelectColumns($criteria);
        $startcol3 = $startcol2 + SoporteUnidadDocumentalPeer::NUM_HYDRATE_COLUMNS;

        EstadoUnidadDocumentalPeer::addSelectColumns($criteria);
        $startcol4 = $startcol3 + EstadoUnidadDocumentalPeer::NUM_HYDRATE_COLUMNS;

        FrecuenciaConsultaPeer::addSelectColumns($criteria);
        $startcol5 = $startcol4 + FrecuenciaConsultaPeer::NUM_HYDRATE_COLUMNS;

        UnidadConservadoraPeer::addSelectColumns($criteria);
        $startcol6 = $startcol5 + UnidadConservadoraPeer::NUM_HYDRATE_COLUMNS;

        SubseriePeer::addSelectColumns($criteria);
        $startcol7 = $startcol6 + SubseriePeer::NUM_HYDRATE_COLUMNS;

        TipoCierreExpedientePeer::addSelectColumns($criteria);
        $startcol8 = $startcol7 + TipoCierreExpedientePeer::NUM_HYDRATE_COLUMNS;

        RegionalPeer::addSelectColumns($criteria);
        $startcol9 = $startcol8 + RegionalPeer::NUM_HYDRATE_COLUMNS;

        $criteria->addJoin(UnidadDocumentalPeer::SOPORTEUNIDADDOCUMENTAL_ID, SoporteUnidadDocumentalPeer::SOPORTEUNIDADDOCUMENTAL_ID, $join_behavior);

        $criteria->addJoin(UnidadDocumentalPeer::ESTADOUNIDADDOCUMENTAL_ID, EstadoUnidadDocumentalPeer::ESTADOUNIDADDOCUMENTAL_ID, $join_behavior);

        $criteria->addJoin(UnidadDocumentalPeer::FRECUENCIACONSULTA_ID, FrecuenciaConsultaPeer::FRECUENCIACONSULTA_ID, $join_behavior);

        $criteria->addJoin(UnidadDocumentalPeer::UNIDADCONSERVADORA_ID, UnidadConservadoraPeer::UNIDADCONSERVADORA_ID, $join_behavior);

        $criteria->addJoin(UnidadDocumentalPeer::SUBSERIE_ID, SubseriePeer::SUBSERIE_ID, $join_behavior);

        $criteria->addJoin(UnidadDocumentalPeer::TIPOCIERREEXPEDIENTE_ID, TipoCierreExpedientePeer::TIPOCIERREEXPEDIENTE_ID, $join_behavior);

        $criteria->addMultipleJoin(array(
        array(UnidadDocumentalPeer::REGIONAL_ID, RegionalPeer::REGIONAL_ID),
        array(UnidadDocumentalPeer::REGIONAL_ID, RegionalPeer::REGIONAL_ID),
      ), $join_behavior);

        // symfony_behaviors behavior
        foreach (sfMixer::getCallables(self::getMixerPreSelectHook(__FUNCTION__)) as $sf_hook)
        {
          call_user_func($sf_hook, 'BaseUnidadDocumentalPeer', $criteria, $con);
        }


        $stmt = BasePeer::doSelect($criteria, $con);
        $results = array();

        while ($row = $stmt->fetch(PDO::FETCH_NUM)) {
            $key1 = UnidadDocumentalPeer::getPrimaryKeyHashFromRow($row, 0);
            if (null !== ($obj1 = UnidadDocumentalPeer::getInstanceFromPool($key1))) {
                // We no longer rehydrate the object, since this can cause data loss.
                // See http://www.propelorm.org/ticket/509
                // $obj1->hydrate($row, 0, true); // rehydrate
            } else {
                $cls = UnidadDocumentalPeer::getOMClass();

                $obj1 = new $cls();
                $obj1->hydrate($row);
                UnidadDocumentalPeer::addInstanceToPool($obj1, $key1);
            } // if obj1 already loaded

                // Add objects for joined SoporteUnidadDocumental rows

                $key2 = SoporteUnidadDocumentalPeer::getPrimaryKeyHashFromRow($row, $startcol2);
                if ($key2 !== null) {
                    $obj2 = SoporteUnidadDocumentalPeer::getInstanceFromPool($key2);
                    if (!$obj2) {
    
                        $cls = SoporteUnidadDocumentalPeer::getOMClass();

                    $obj2 = new $cls();
                    $obj2->hydrate($row, $startcol2);
                    SoporteUnidadDocumentalPeer::addInstanceToPool($obj2, $key2);
                } // if $obj2 already loaded

